	// Traverse rows (dimension 'i') explicitly to keep row-major locality (`j` is inner).
	traverser(A, B).template for_dims<'i'>([&](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // contains index in 'i'
		auto i  = get_index<'i'>(si);

		// x[i]  — x is indexed by 'j', so we use j = i
		x[idx<'j'>(i)] = (num_t)(i % n) / n;

		// A[i][j], B[i][j]
		inner.for_each([&](auto s) {
			auto j = get_index<'j'>(s);

			A[s] = (num_t)((i * j + 1) % n) / n;
			B[s] = (num_t)((i * j + 2) % n) / n;
		});
	});
}

// computation kernel
//
// Optimization summary vs. original:
// - Keep outer loop over 'i' (rows) and inner over 'j' (columns) to respect
//   row‑major layout (good spatial locality in A, B, and x).
// - Use scalar accumulators (tmp_acc, y_acc) in registers instead of
//   repeatedly reading/writing tmp[i] and y[i] inside the inner loop.
//   This removes loop‑carried memory dependencies on tmp and y, aiding
//   vectorization and reducing memory traffic.
// - Reuse the full index state `s` to access x[s]; x only uses 'j',
//   so the additional 'i' dimension is ignored. This avoids extra
//   index construction per iteration.
//
[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	// Original C:
	// for (i = 0; i < _PB_N; i++) {
	//   tmp[i] = 0.0;
	//   y[i] = 0.0;
	//   for (j = 0; j < _PB_N; j++) {
	//     tmp[i] = A[i][j] * x[j] + tmp[i];
	//     y[i]   = B[i][j] * x[j] + y[i];
	//   }
	//   y[i] = alpha * tmp[i] + beta * y[i];
	// }

	#pragma scop
	traverser(A, B, tmp, x, y).template for_dims<'i'>([&](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // state with fixed 'i'

		// Use register accumulators for the reductions over j.
		num_t tmp_acc = (num_t)0.0;
		num_t y_acc   = (num_t)0.0;

		// Inner loop over j: accumulate dot products for this row i.
		inner.for_each([&](auto s) {
			// s contains both 'i' and 'j'.
			// x depends only on 'j', but using the full state is allowed;
			// the extra 'i' component is ignored by the x-structure.
			const num_t xj = x[s];

			tmp_acc += A[s] * xj;
			y_acc   += B[s] * xj;
		});

		// Write back final values for row i.
		tmp[si] = tmp_acc;
		y[si]   = alpha * tmp_acc + beta * y_acc;
	});
	#pragma endscop
}

